// =====================================================

#define LED_PIN        27
#define LED_COUNT      50
#define LED_BRIGHTNESS 150

Adafruit_NeoPixel strip(
  LED_COUNT,
  LED_PIN,
  NEO_GRB + NEO_KHZ800
);

// =====================================================
// WEB SERVER
// =====================================================

WebServer server(80);

// =====================================================
// OTA WEB PAGE
// =====================================================

