// =====================================================
// SET ALL LEDS
// =====================================================

void setAll(byte r, byte g, byte b) {

  for (int i = 0; i < LED_COUNT; i++) {

    strip.setPixelColor(
      i,
      strip.Color(r, g, b)
    );

  }

  strip.show();
}


// =====================================================
// OTA
// =====================================================

void setupOTA() {

  server.on("/", HTTP_GET, []() {

    server.send(
      200,
      "text/html",
      updatePage
    );

  });


  server.on(

    "/update",

    HTTP_POST,

    []() {

      if (Update.hasError()) {

        server.send(
          500,
          "text/plain",
          "UPDATE FAILED"
        );

      }

      else {

        server.send(
          200,
          "text/plain",
          "UPDATE SUCCESSFUL - REBOOTING"
        );

        delay(1000);

        ESP.restart();

      }

    },


    []() {

      HTTPUpload& upload = server.upload();


      if (upload.status == UPLOAD_FILE_START) {

        Serial.println("OTA UPDATE STARTING");

        if (!Update.begin(UPDATE_SIZE_UNKNOWN)) {

          Update.printError(Serial);

        }

      }


      else if (upload.status == UPLOAD_FILE_WRITE) {

        if (
          Update.write(
            upload.buf,
            upload.currentSize
          ) != upload.currentSize
        ) {

          Update.printError(Serial);

        }

      }


      else if (upload.status == UPLOAD_FILE_END) {

        if (Update.end(true)) {

          Serial.println(
            "OTA UPDATE SUCCESSFUL"
          );

        }

        else {

          Update.printError(Serial);

        }

      }

    }

  );


  server.begin();

}


// =====================================================
// SETUP
// =====================================================

void setup() {

  Serial.begin(115200);

  strip.begin();

  strip.setBrightness(
    LED_BRIGHTNESS
  );

  strip.clear();
  strip.show();


  // CONNECT WIFI

  WiFi.mode(WIFI_STA);

  WiFi.begin(
    ssid,
    password
  );


  while (
    WiFi.status() != WL_CONNECTED
  ) {

    delay(500);

  }


  Serial.print("IP: ");
  Serial.println(WiFi.localIP());


  setupOTA();

}


// =====================================================
// LOOP
// =====================================================

void loop() {

  server.handleClient();


  static unsigned long lastChange = 0;

  static int color = 0;


  if (millis() - lastChange >= 2000) {

    lastChange = millis();


    // --------------------------
    // COMMAND RED
    // --------------------------

    if (color == 0) {

      setAll(255, 0, 0);

    }


    // --------------------------
    // COMMAND GREEN
    // --------------------------

    else if (color == 1) {

      setAll(0, 255, 0);

    }


    // --------------------------
    // COMMAND BLUE
    // --------------------------

    else {

      setAll(0, 0, 255);

    }


    color++;

    if (color > 2) {

      color = 0;

    }

  }

}
